DROP TABLE IF EXISTS `letterheads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `letterheads` (
  `id` int(11) NOT NULL DEFAULT 1,
  `html` longtext DEFAULT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `letterheads`
--

LOCK TABLES `letterheads` WRITE;
/*!40000 ALTER TABLE `letterheads` DISABLE KEYS */;
INSERT INTO `letterheads` VALUES (1,'<div style=\"margin:0;padding:0;background:#eff6ff;font-family:Arial,Helvetica,sans-serif;\">\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eff6ff;padding:24px 0;\">\n    <tr><td align=\"center\">\n      <table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:640px;max-width:100%;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(30,64,175,.10);\">\n        <tr><td style=\"background:#1e88e5;padding:22px 28px;\">\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tr>\n            <td style=\"vertical-align:middle;\">\n              <div style=\"color:#ffffff;font-size:19px;font-weight:bold;letter-spacing:.3px;\">{{company_name}}</div>\n              <div style=\"color:#cfe4fb;font-size:11px;line-height:1.6;margin-top:4px;\">\n                Devon Rd, Hempstead, NY &nbsp;|&nbsp; yourinfo@emailaddress.com<br>\n                www.yourcompany.com &nbsp;|&nbsp; 222 555 7777\n              </div>\n            </td>\n            <td align=\"right\" style=\"vertical-align:middle;\">{{logo}}</td>\n          </tr></table>\n        </td></tr>\n        <tr><td style=\"padding:28px 28px 4px 28px;\">\n          <h1 style=\"margin:0;font-size:23px;font-weight:bold;color:#0b4a8f;text-align:center;\">{{title}}</h1>\n        </td></tr>\n        <tr><td style=\"padding:14px 28px 28px 28px;font-size:14px;line-height:1.7;color:#374151;\">{{content}}</td></tr>\n        <tr><td style=\"background:#f5f9ff;padding:14px 28px;border-top:1px solid #dbeafe;text-align:center;\">\n          <span style=\"font-size:11px;color:#7aa7d6;\">Sent by {{company_name}} on {{date}}</span>\n        </td></tr>\n      </table>\n    </td></tr>\n  </table>\n</div>',1,'2026-08-05 10:55:22.512');
/*!40000 ALTER TABLE `letterheads` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `price_list_items`
