DROP TABLE IF EXISTS `price_list_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `price_list_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `document_id` int(11) NOT NULL,
  `category_id` int(11) DEFAULT NULL,
  `brand` varchar(80) NOT NULL,
  `family` varchar(160) DEFAULT NULL,
  `type` varchar(160) DEFAULT NULL,
  `catalog_no` varchar(160) NOT NULL,
  `description` text NOT NULL,
  `poles` int(11) DEFAULT NULL,
  `rating_amp` decimal(10,2) DEFAULT NULL,
  `rating_amp_min` decimal(10,2) DEFAULT NULL,
  `rating_amp_max` decimal(10,2) DEFAULT NULL,
  `breaking_ka` decimal(10,2) DEFAULT NULL,
  `list_price` decimal(12,2) NOT NULL,
  `unit` varchar(40) DEFAULT NULL,
  `page_no` int(11) DEFAULT NULL,
  `raw_text` text DEFAULT NULL,
  `attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`attributes`)),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `price_list_items_document_id_idx` (`document_id`),
  KEY `price_list_items_category_id_brand_idx` (`category_id`,`brand`),
  KEY `price_list_items_catalog_no_idx` (`catalog_no`),
  KEY `price_list_items_brand_rating_amp_idx` (`brand`,`rating_amp`),
  CONSTRAINT `price_list_items_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `product_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `price_list_items_document_id_fkey` FOREIGN KEY (`document_id`) REFERENCES `product_documents` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10612 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

