INSERT INTO `roles` VALUES (1,'Administrator','Full access to everything.','[\"*\"]',1,'2026-08-02 09:01:47.174','2026-08-02 11:38:10.513'),(2,'Manager','Manage catalogue, customers and quotes (no user/role admin).','[\"dashboard.view\",\"companies.view\",\"companies.create\",\"companies.edit\",\"categories.view\",\"categories.create\",\"categories.edit\",\"customers.view\",\"customers.create\",\"customers.edit\",\"jobwork.view\",\"jobwork.create\"]',0,'2026-08-02 09:01:47.215','2026-08-05 06:24:03.842'),(3,'Viewer','Read-only access.','[\"dashboard.view\",\"companies.view\",\"categories.view\",\"customers.view\",\"jobwork.view\"]',0,'2026-08-02 09:01:47.246','2026-08-02 09:01:47.246');
